import base64,gzip,json,pathlib,subprocess,sys
root=pathlib.Path('/content/gliner-plan');root.mkdir(exist_ok=True)
for name,content in json.loads(gzip.decompress(base64.b64decode(''))).items():
 target=root/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
r=subprocess.run([sys.executable,'-m','pip','install','-q','gliner','flashdeberta'],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
print(r.stdout[-12000:],flush=True);r.check_returncode()
